// The only place to configure this workflow.
const TELEGRAM_CHAT_ID = '';  // put your Telegram chat ID here   // commercial director's Telegram chat ID. Empty = log only, no message.
const j = $input.first().json;
const fromWebhook = !!j.headers;
const body = j.body || {};
const asked = body.source || '';
// replay_day lets the dashboard replay a past day of the synthetic data; anything that is not YYYY-MM-DD is ignored.
const day = /^\d{4}-\d{2}-\d{2}$/.test(String(body.replay_day || '')) ? body.replay_day : null;
return [{ json: {
  source: fromWebhook ? (['dashboard', 'manual'].includes(asked) ? asked : 'api') : 'schedule',
  from_webhook: fromWebhook,
  chat_id: String(TELEGRAM_CHAT_ID).trim(),
  replay_day: fromWebhook ? day : null
} }];

// Every number below comes straight from discount_guardrail(); this node only formats them.
// Definition (same as the dashboard): lines discounted above 15%; EGP = the part of their discount above a 10% cap.
const g = $input.first().json;
const cfg = $('Config').first().json;
if (g.ok === false) {
  const summary = 'Guardrail did not run: ' + g.error + '.';
  return [{ json: { status: 'error', summary, text: summary, send_telegram: false,
    log_row: { workflow: 'guardrail', source: cfg.source, status: 'error', data_day: null, summary, payload: g },
    response: { status: 'error', summary } } }];
}
const nf = n => Number(n || 0).toLocaleString('en-US');
const ch = (g.by_channel || [])[0];
const cat = (g.by_category || [])[0];
const top = (g.top_lines || [])[0];
const isAlert = g.status === 'alert';
let summary;
if (!g.lines) {
  summary = g.day + ': no invoice line discounted above 15%. Status: normal.';
} else {
  summary = g.day + ': ' + nf(g.lines) + ' invoice lines discounted above 15%, ' + nf(g.excess_egp) + ' EGP given above a 10% cap ('
    + g.vs_baseline + 'x the 28-day median of ' + nf(g.baseline_median_excess_egp) + ' EGP). Biggest channel: '
    + (ch ? ch.channel + ' ' + nf(ch.excess_egp) + ' EGP' : 'n/a') + '. Status: ' + (isAlert ? 'ALERT' : 'normal')
    + '. Last 12 months: ' + nf(g.l12m_lines) + ' lines, ' + nf(g.l12m_excess_egp) + ' EGP.';
}
const action = !isAlert ? 'مفيش حاجة مطلوبة، اليوم في المعدل الطبيعي.'
  : (ch && /Wholesale/i.test(ch.channel)
    ? 'راجع موافقات خصم الجملة النهارده، وخلي أي خصم فوق 15% يحتاج موافقة مدير المبيعات.'
    : 'راجع مع مديري الفروع/الأونلاين الخصومات اليدوية النهارده في ' + (ch ? ch.channel : 'القناة دي') + '.');
const text = (isAlert ? '⚠️ تنبيه خصومات' : '✅ تقرير الخصومات') + ' — ' + g.day + '\n\n'
  + nf(g.lines) + ' سطر فاتورة بخصم أكتر من 15%.\n'
  + 'الخصم اللي اتدى فوق سقف 10%: ' + nf(g.excess_egp) + ' جنيه (' + g.vs_baseline + '× متوسط آخر 28 يوم).\n'
  + (ch ? 'أكتر قناة: ' + ch.channel + ' (' + nf(ch.excess_egp) + ' جنيه، ' + ch.lines + ' سطر)\n' : '')
  + (cat ? 'أكتر قسم: ' + cat.category + ' (' + nf(cat.excess_egp) + ' جنيه)\n' : '')
  + (top ? 'أكبر سطر: ' + top.sales_line_id + ' — ' + top.channel + '، ' + top.category + '، خصم ' + top.discount_pct + '%\n' : '')
  + '\nالمطلوب: ' + action;
const status = isAlert ? 'alert' : 'ok';
return [{ json: {
  status, summary, text,
  send_telegram: cfg.chat_id !== '' && (isAlert || cfg.source === 'dashboard'),
  log_row: { workflow: 'guardrail', source: cfg.source, status, data_day: g.day, summary, payload: g },
  response: { status, summary, day: g.day, lines: g.lines, excess_egp: g.excess_egp, vs_baseline: g.vs_baseline,
              by_channel: g.by_channel, top_lines: g.top_lines, telegram: cfg.chat_id !== '' }
} }];
